#!/usr/bin/env bash
# Sync docs/ → GitHub Wiki of AgileFactory/kernel.
#
# Authoritative source: docs/. The wiki is a flattened mirror generated by
# this script and pushed by CI on every push to main. GitHub wikis don't
# support sub-directories; we rename per RFC-0038 to keep titles unique:
#
#   docs/architecture/overview.md                 → Architecture-Overview.md
#   docs/architecture/file-structure.md           → File-Structure.md
#   docs/architecture/technical-deepdive.md       → Technical-Deepdive.md
#   docs/architecture/diagrams/<name>.md          → Diagram-<Name>.md
#   docs/architecture/rfcs/NNNN-Title.md          → RFC-NNNN-Title.md
#   docs/architecture/adrs/NNNN-Title.md          → ADR-NNNN-Title.md
#   docs/development/conventions.md               → Conventions.md
#   docs/development/integration-guide.md         → Integration-Guide.md
#   docs/operations/runbook.md                    → Runbook.md
#
# NOT mirrored: docs/api/openapi.yaml (YAML, link only from Home.md).
#
# Plus generated:
#   Home.md      — landing page grouped by type
#   _Sidebar.md  — global navigation
#
# Internal markdown links are rewritten so the wiki cross-references resolve.
#
# Usage:
#   GITHUB_TOKEN=... ./scripts/sync-wiki.sh          # production (clones, pushes)
#   WIKI_DIR=/tmp/kernel-wiki ./scripts/sync-wiki.sh # dry: writes into WIKI_DIR
#                                                   # (no clone, no push)

set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC_DOCS="$ROOT/docs"

REPO_OWNER="${REPO_OWNER:-AgileFactory}"
REPO_NAME="${REPO_NAME:-kernel}"

# Output dir. In CI, we let the script clone the wiki repo; for local dry
# runs the caller can point WIKI_DIR at a scratch directory to skip auth.
WIKI_DIR="${WIKI_DIR:-}"
CLONED=false
if [[ -z $WIKI_DIR ]]; then
  WIKI_DIR="$(mktemp -d -t kernel-wiki-XXXXXX)"
  CLONED=true
else
  # Dry-run path — make sure the directory exists so the rest of the
  # script can operate without special cases.
  mkdir -p "$WIKI_DIR"
fi

bold()  { printf '\033[1m%s\033[0m\n' "$*"; }
green() { printf '\033[32m%s\033[0m\n' "$*"; }
red()   { printf '\033[31m%s\033[0m\n' "$*" >&2; }

cleanup() {
  if [[ $CLONED == true && -d $WIKI_DIR ]]; then
    rm -rf "$WIKI_DIR"
  fi
}
trap cleanup EXIT

# ─── 1. Clone the wiki repo (production path) ────────────────────────────────
if [[ $CLONED == true ]]; then
  if [[ -z ${GITHUB_TOKEN:-} ]]; then
    red "GITHUB_TOKEN is required to clone the wiki repo."
    red "For a local dry-run, set WIKI_DIR to a scratch directory instead."
    exit 1
  fi
  bold "→ Cloning ${REPO_OWNER}/${REPO_NAME}.wiki"
  clone_err=$(mktemp)
  if git clone --quiet --depth=1 \
      "https://x-access-token:${GITHUB_TOKEN}@github.com/${REPO_OWNER}/${REPO_NAME}.wiki.git" \
      "$WIKI_DIR" 2>"$clone_err"; then
    rm -f "$clone_err"
  else
    if grep -qi "Repository not found\|not found" "$clone_err"; then
      red "Wiki repository does not yet exist on GitHub."
      red ""
      red "GitHub provisions the .wiki.git repo lazily — only after the first"
      red "page has been authored through the web UI. A local 'git init' here"
      red "cannot work around that; any push will keep failing with 404."
      red ""
      red "One-time bootstrap (≈30 seconds):"
      red "  1. Open https://github.com/${REPO_OWNER}/${REPO_NAME}/settings"
      red "     → Features → tick 'Wikis'."
      red "  2. Open https://github.com/${REPO_OWNER}/${REPO_NAME}/wiki"
      red "     → 'Create the first page' → leave any content → 'Save Page'."
      red "  3. Re-run this workflow from the Actions tab."
      red ""
      red "From then on this script mirrors docs/ into the wiki on every push."
    else
      red "Failed to clone wiki repository:"
      sed 's/^/  /' "$clone_err" >&2
    fi
    rm -f "$clone_err"
    exit 1
  fi
fi

# Wipe everything except .git — full mirror semantics avoid stale pages
# when a doc gets deleted upstream.
bold "→ Resetting wiki working tree (preserves .git)"
find "$WIKI_DIR" -mindepth 1 -maxdepth 1 \! -name '.git' -exec rm -rf {} +

# ─── 2. Helpers ──────────────────────────────────────────────────────────────

# is_empty returns 0 if a file is empty or whitespace-only.
is_empty() {
  ! grep -q '[^[:space:]]' "$1" 2>/dev/null
}

# rewrite_links takes the source file path + target path and applies the
# global link transformations. The source path is used to know whether bare
# `NNNN-X.md` refs should become RFC-* or ADR-*.
rewrite_links() {
  local src="$1" dst="$2"
  local domain=""
  case "$src" in
    */rfcs/*) domain="rfc" ;;
    */adrs/*) domain="adr" ;;
    *)        domain="other" ;;
  esac

  # Order matters: explicit prefixes first, then bare same-dir.
  #   1. `../rfcs/NNNN-X.md` (with or without ./) → `RFC-NNNN-X`
  #   2. `../adrs/NNNN-X.md`                      → `ADR-NNNN-X`
  #   3. `architecture/diagrams/<name>.md`        → `Diagram-<Name>`
  #   4. `architecture/overview.md` (and variants) → `Architecture-Overview`
  #   5. `architecture/file-structure.md`         → `File-Structure`
  #   6. `architecture/technical-deepdive.md`     → `Technical-Deepdive`
  #   7. `development/conventions.md`             → `Conventions`
  #   8. `development/integration-guide.md`       → `Integration-Guide`
  #   9. `operations/runbook.md`                  → `Runbook`
  #  10. bare `NNNN-X.md` if domain matches       → `RFC|ADR-NNNN-X`
  sed -E \
    -e 's|\.\./?rfcs/([0-9]{4})-([^).]+)\.md|RFC-\1-\2|g' \
    -e 's|\.\./?adrs/([0-9]{4})-([^).]+)\.md|ADR-\1-\2|g' \
    -e 's|\.\./?architecture/diagrams/([a-z0-9-]+)\.md|Diagram-\1|g' \
    -e 's|\.\./?architecture/overview\.md|Architecture-Overview|g' \
    -e 's|\.\./?architecture/file-structure\.md|File-Structure|g' \
    -e 's|\.\./?architecture/technical-deepdive\.md|Technical-Deepdive|g' \
    -e 's|\.\./?development/conventions\.md|Conventions|g' \
    -e 's|\.\./?development/integration-guide\.md|Integration-Guide|g' \
    -e 's|\.\./?operations/runbook\.md|Runbook|g' \
    -e 's|\boverview\.md\b|Architecture-Overview|g' \
    -e 's|\bfile-structure\.md\b|File-Structure|g' \
    -e 's|\btechnical-deepdive\.md\b|Technical-Deepdive|g' \
    -e 's|\bconventions\.md\b|Conventions|g' \
    -e 's|\bintegration-guide\.md\b|Integration-Guide|g' \
    -e 's|\brunbook\.md\b|Runbook|g' \
    "$src" > "$dst"

  # Pass 2: bare `NNNN-X.md` in the source's own domain. We restrict to
  # same-line matches around markdown link parens / brackets to avoid
  # mangling unrelated text that happens to contain "0001-foo.md".
  case "$domain" in
    rfc)
      sed -i -E 's|([(\[ ])([0-9]{4})-([^).]+)\.md|\1RFC-\2-\3|g' "$dst"
      ;;
    adr)
      sed -i -E 's|([(\[ ])([0-9]{4})-([^).]+)\.md|\1ADR-\2-\3|g' "$dst"
      ;;
  esac
}

# copy_and_rewrite copies a source file to the wiki under the given target
# name, applying link rewriting in the process.
copy_and_rewrite() {
  local src="$1" name="$2"
  if is_empty "$src"; then
    bold "  - skip $src (empty)"
    return
  fi
  rewrite_links "$src" "$WIKI_DIR/$name"
}

# ─── 3. Copy + rename per the mapping ────────────────────────────────────────
bold "→ Mapping docs/ → wiki pages"

# Flat root entries.
copy_and_rewrite "$SRC_DOCS/architecture/overview.md"           "Architecture-Overview.md"
copy_and_rewrite "$SRC_DOCS/architecture/file-structure.md"     "File-Structure.md"
copy_and_rewrite "$SRC_DOCS/architecture/technical-deepdive.md" "Technical-Deepdive.md"
copy_and_rewrite "$SRC_DOCS/development/conventions.md"         "Conventions.md"
copy_and_rewrite "$SRC_DOCS/development/integration-guide.md"   "Integration-Guide.md"
copy_and_rewrite "$SRC_DOCS/operations/runbook.md"              "Runbook.md"

# Diagrams: docs/architecture/diagrams/<name>.md → Diagram-<Name>.md
# (capitalise first letter; everything else stays kebab — wiki collapses
# both 'Diagram-Erd' and 'Diagram-erd' to the same slug)
if [[ -d $SRC_DOCS/architecture/diagrams ]]; then
  while IFS= read -r f; do
    base="$(basename "$f" .md)"
    cap="$(echo "$base" | sed -E 's/^(.)/\U\1/')"
    copy_and_rewrite "$f" "Diagram-${cap}.md"
  done < <(find "$SRC_DOCS/architecture/diagrams" -maxdepth 1 -type f -name '*.md' | sort)
fi

# RFCs — pattern matches `NNNN-Title[.md]` (the legacy 0003 file misses .md).
while IFS= read -r f; do
  base="$(basename "$f")"
  base="${base%.md}"
  copy_and_rewrite "$f" "RFC-${base}.md"
done < <(find "$SRC_DOCS/architecture/rfcs" -maxdepth 1 -type f \
  \( -name '[0-9][0-9][0-9][0-9]-*.md' -o -name '[0-9][0-9][0-9][0-9]-*' \) \
  -not -name 'template*' | sort)

# ADRs.
while IFS= read -r f; do
  base="$(basename "$f" .md)"
  copy_and_rewrite "$f" "ADR-${base}.md"
done < <(find "$SRC_DOCS/architecture/adrs" -maxdepth 1 -type f \
  -name '[0-9][0-9][0-9][0-9]-*.md' -not -name 'template*' | sort)

# ─── 4. Generate Home.md + _Sidebar.md ───────────────────────────────────────
bold "→ Generating Home + _Sidebar"

{
  echo "# AgileFactory / kernel — Wiki"
  echo
  echo "> Auto-generated from \`docs/\` on every push to \`main\` by \`scripts/sync-wiki.sh\`."
  echo "> Edit the source files under \`docs/\` in the [main repo](https://github.com/${REPO_OWNER}/${REPO_NAME}) — changes flow back here on the next CI run."
  echo
  echo "## Démarrer"
  echo
  echo "- [Integration Guide](Integration-Guide) — tutoriel pas-à-pas pour intégrer kernel dans un repo SaaS."
  echo "- [Architecture Overview](Architecture-Overview) — stack, layering, profils (SaaS B2B, B2B2C, BaaS)."
  echo "- [File Structure](File-Structure) — plan du repo et conventions de packaging."
  echo "- [Conventions](Conventions) — naming, formatting, contribution rules."
  echo
  echo "## Approfondir"
  echo
  echo "- [Technical deep-dive](Technical-Deepdive) — invariants critiques (outbox, txctx, AppError, multi-tenancy…)."
  echo "- [Runbook](Runbook) — procédures d'exploitation : deploy, migrations, rollback, outbox stuck."
  echo "- OpenAPI 3 : [openapi.yaml](https://github.com/${REPO_OWNER}/${REPO_NAME}/blob/main/docs/api/openapi.yaml) (rendu via Swagger UI / Redoc)."
  echo
  echo "## Diagrammes"
  echo
  while IFS= read -r f; do
    base="$(basename "$f" .md)"
    title="$(head -1 "$f" | sed -E 's/^# *//')"
    [[ -z $title ]] && title="$base"
    echo "- [${title}](${base})"
  done < <(find "$WIKI_DIR" -maxdepth 1 -name 'Diagram-*.md' -type f | sort)
  echo
  echo "## RFCs"
  echo
  while IFS= read -r f; do
    base="$(basename "$f" .md)"
    # H1 variants: `# _RFC #N:_ Title` (italic underscore), `# *RFC #N:*
    # Title` (italic asterisk), `# RFC-N: Title`, or bare `# Title`.
    title="$(head -1 "$f" | sed -E 's/^# *[_*]?RFC #?([0-9]+):[_*]? *(.*)$/RFC-\1 — \2/; s/^# *//')"
    [[ -z $title ]] && title="$base"
    echo "- [${title}](${base})"
  done < <(find "$WIKI_DIR" -maxdepth 1 -name 'RFC-*.md' -type f | sort)
  echo
  echo "## ADRs"
  echo
  while IFS= read -r f; do
    base="$(basename "$f" .md)"
    title="$(head -1 "$f" | sed -E 's/^# *[_*]?ADR #?([0-9]+):[_*]? *(.*)$/ADR-\1 — \2/; s/^# *//')"
    [[ -z $title ]] && title="$base"
    echo "- [${title}](${base})"
  done < <(find "$WIKI_DIR" -maxdepth 1 -name 'ADR-*.md' -type f | sort)
} > "$WIKI_DIR/Home.md"

{
  echo "**[Home](Home)**"
  echo
  echo "**Démarrer**"
  echo
  echo "- [Integration Guide](Integration-Guide)"
  echo "- [Architecture](Architecture-Overview)"
  echo "- [Structure du repo](File-Structure)"
  echo "- [Conventions](Conventions)"
  echo
  echo "**Approfondir**"
  echo
  echo "- [Technical deep-dive](Technical-Deepdive)"
  echo "- [Runbook](Runbook)"
  echo
  echo "**Diagrammes**"
  echo
  while IFS= read -r f; do
    base="$(basename "$f" .md)"
    echo "- [${base#Diagram-}](${base})"
  done < <(find "$WIKI_DIR" -maxdepth 1 -name 'Diagram-*.md' -type f | sort)
  echo
  echo "**RFCs**"
  echo
  while IFS= read -r f; do
    base="$(basename "$f" .md)"
    echo "- [${base}](${base})"
  done < <(find "$WIKI_DIR" -maxdepth 1 -name 'RFC-*.md' -type f | sort)
  echo
  echo "**ADRs**"
  echo
  while IFS= read -r f; do
    base="$(basename "$f" .md)"
    echo "- [${base}](${base})"
  done < <(find "$WIKI_DIR" -maxdepth 1 -name 'ADR-*.md' -type f | sort)
} > "$WIKI_DIR/_Sidebar.md"

# ─── 5. Commit + push (production path only) ─────────────────────────────────
bold "→ Result"
ls "$WIKI_DIR" | sort | sed 's/^/    /'

if [[ $CLONED == true ]]; then
  cd "$WIKI_DIR"
  git add -A
  if git diff --cached --quiet; then
    green "✓ Wiki already up-to-date."
    exit 0
  fi
  git -c user.email="ci-bot@agilefactory.local" \
      -c user.name="kernel-wiki-sync" \
      commit --quiet -m "docs: sync from kernel@${GITHUB_SHA:-HEAD}"
  # GitHub wikis use `master` as their default branch regardless of the
  # main repo default. Push explicitly against it.
  push_err=$(mktemp)
  if ! git push --quiet origin HEAD:master 2>"$push_err"; then
    red "Push to wiki failed:"
    sed 's/^/  /' "$push_err" >&2
    if grep -qi "permission denied\|403" "$push_err"; then
      red ""
      red "The default GITHUB_TOKEN can't push to this wiki. Generate a PAT"
      red "with 'repo' scope and store it as secrets.WIKI_TOKEN; the workflow"
      red "is already wired to prefer WIKI_TOKEN over the default token."
    fi
    rm -f "$push_err"
    exit 1
  fi
  rm -f "$push_err"
  green "✓ Wiki pushed."
else
  green "✓ Wiki tree written to $WIKI_DIR (no push)."
fi
